#include <libssh2.h>
#include <libssh2_sftp.h>

int main() {
    // Initialize SSH2 session
    libssh2_session *session = libssh2_session_init();
    if (!session) {
        cout << "Failed to initialize SSH2 session" << endl;
        return 1;
    }

    // Connect to the server
    if (libssh2_connect(session, "example.com", 22) != LIBSSH2_ERROR_NONE) {
        cout << "Failed to connect to the server" << endl;
        libssh2_session_free(session);
        return 1;
    }

    // Login to the server
    if (libssh2_userauth_password(session, "username", "password") != LIBSSH2_AUTH_SUCCESS) {
        cout << "Failed to login to the server" << endl;
        libssh2_session_free(session);
        return 1;
    }

    // Initialize SFTP
    libssh2_sftp *sftp = libssh2_sftp_init(session);
    if (!sftp) {
        cout << "Failed to initialize SFTP" << endl;
        libssh2_session_free(session);
        return 1;
    }

    // Open a file on the remote server
    libssh2_sftp_file *file = libssh2_sftp_open(sftp, "/path/to/file", O_WRONLY | O_CREAT, 0644);
    if (!file) {
        cout << "Failed to open a file" << endl;
        libssh2_sftp_free(sftp);
        libssh2_session_free(session);
        return 1;
    }

    // Upload a file
    FILE *local_file = fopen("local_file", "rb");
    if (!local_file) {
        cout << "Failed to open the local file" << endl;
        libssh2_sftp_file_free(file);
        libssh2_sftp_free(sftp);
        libssh2_session_free(session);
        return 1;
    }

    char buffer[1024];
    while (fread(buffer, 1, 1024, local_file) > 0) {
        libssh2_sftp_file_write(file, buffer, 1024);
    }

    fclose(local_file);
    libssh2_sftp_file_close(file);

    // Close SFTP and SSH2 session
    libssh2_sftp_free(sftp);
    libssh2_session_free(session);

    return 0;
}
```

